FINALS = [
    'libfile -c o.TabDialogL o.tabd_TabDialog',
    'libfile -via libviaPane',
    'link -via linkvia',
    'CDir out',
    'Copy RDPClient out.RDPClient ~C~V',
]

def run(cmd):
    # RISC OS: os.system maps to OS_CLI; redirect output to a log we can show.
    return os.system(cmd + ' { > o.buildlog 2>&1 }')

def main():
    if DDE_DIR:
        if os.system("Obey " + DDE_DIR + ".!SetPaths"):
            sys.stdout.write("*** !SetPaths failed - check DDE_DIR (" + DDE_DIR + ")\n")
            return 1
    for s in SETUP:
        os.system(s)
    built = skipped = 0
    for out, cmd in COMPILES:
        if out and os.path.exists(out):
            skipped += 1
            continue
        sys.stdout.write("cc " + out + "\n")
        if run("cc -c " + EXTRA + cmd):
            sys.stdout.write("\n*** FAILED: " + out + "\n")
            try: sys.stdout.write(open("o.buildlog").read())
            except: pass
            return 1
        built += 1
    sys.stdout.write("compiled %d, skipped %d; linking...\n" % (built, skipped))
    for f in FINALS:
        if os.system(f):
            sys.stdout.write("*** step failed: " + f + "\n")
            return 1
    os.system("SetType out.RDPClient FF8")
    sys.stdout.write("done -> out.RDPClient (Absolute, &FF8)\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
